use llm_wiki_desktop_lib::{models::import_v2_web::WebImportErrorCode,services::import_v2::{domain_router::{ConnectorAvailability,DomainRouter},url_policy::UrlPolicy}};
#[test]fn stage_one_routes_and_stable_errors_are_frozen(){let a=ConnectorAvailability{browser:true,wechat:true,zhihu:true,bilibili:true,phase_two:false};for host in ["mp.weixin.qq.com","www.zhihu.com","www.bilibili.com"]{let t=UrlPolicy.normalize_for_session(&format!("https://{host}/one?token=secret#frag")).unwrap();let p=DomainRouter::plan(&t.public,&a);assert!(p.release_enabled);assert!(!serde_json::to_string(&t.public).unwrap().contains("secret"));}assert_eq!(serde_json::to_value(WebImportErrorCode::PrivateTargetBlocked).unwrap(),"private_target_blocked");}
#[test]fn phase_two_stays_closed_without_gate(){let a=ConnectorAvailability{browser:true,wechat:true,zhihu:true,bilibili:true,phase_two:false};for host in ["www.xiaohongshu.com","x.com"]{let t=UrlPolicy.normalize_for_session(&format!("https://{host}/one")).unwrap();assert!(!DomainRouter::plan(&t.public,&a).release_enabled);}}
